INTRO = 'Ambushing Cindy at dawn, the crew catches her bare-faced in bed, only for Cindy to politely turn down Seung-chan\'s iced fish-sauce coffee and later smell fish sauce leaking in his backpack. Listen for "naemsae", a smell or odor.'
STORY = [('cindy', '나 아침에 아이스는 안 마셔요, 죄송.', "I don't drink iced drinks in the morning, sorry.", [(861, '나 아침에 아이스는 안 마셔요, 죄송')], ''), ('joonmo', '보안이 너무 철저했나 봐. 정말 몰랐던 눈치야.', 'Our security must have been super tight. She genuinely had no idea.', [(862, '보안이 너무 철저했나 봐요'), (863, '정말 몰랐던 눈치야')], ''), ('joonmo', '예상을 전혀 못 한 것 같고 작전으로는 성공인데 희한하네.', "She didn't expect it at all, so the operation succeeded, yet something feels odd.", [(865, '예상을 전혀 못 한 거 같고'), (866, '일단 작전으로는 성공인데')], ''), ('joonmo', '신디 씨가 오늘 뭐 연기하신 거 있어요?', 'Did Cindy put on any acting today?', [(868, '신디 씨가 오늘 뭐 연기하신 거 있어요')], ''), ('cindy', '이 신발은 너무 신경 쓴 것 같잖아, 털털한 이미지인데.', 'These shoes look like I tried too hard when I am going for an easygoing image.', [(871, '너무 신경 쓴 거 같잖아')], ''), ('cindy', '아니 그렇다고 이렇게 낡은 걸 어떻게 신어?', 'Still, how am I supposed to wear shoes this worn out?', [(873, '아니 그렇다고 이렇게'), (873, '어떻게 신어')], ''), ('seungchan', '다들 기다리고 계셔서 모시고 오라고 해서요.', 'Everyone is waiting, so they sent me to escort you over.', [(874, '다들 기다리고 계셔서'), (875, '모시고 오라고 해서요')], ''), ('cindy', '촬영 가는 동안 여기 전문 업체 불러서 소독해.', 'While we are off filming, call a professional company and sanitize my room.', [(877, '촬영 가는 동안 여기 청소해'), (878, '아니 소독해 전문 업체 불러서')], ''), ('cindy', '아, 무슨 냄새야 진짜?', 'Ugh, what on earth is that smell?', [(880, '아 무슨 냄새야 진짜')], ''), ('seungchan', '아, 이건 제 냄새는 아니고요.', 'Oh, that smell is not coming from me.', [(882, '제 냄새는 아니고요')], ''), ('seungchan', '배낭에 지금 저희 소품 까나리가 있는데 그게 좀 새 가지고요.', 'We have fish-sauce props in my backpack right now, and some of it leaked.', [(883, '배낭에 지금 저희 소품'), (884, '까나리가 있는데'), (885, '그게 지금 좀 새가지고')], ''), ('cindy', '네, 알겠어요.', 'Right, I understand.', [(886, '네 알겠어요')], '')]
OPENER = "Now let's go through it line by line with the English translation."
WALK = [(0, None, "'I don't drink iced drinks in the morning, sorry.'"), (1, None, "'Our security must have been super tight. She genuinely had no idea.'"), (2, None, "'She didn't expect it at all, so the operation succeeded, yet something feels odd.'"), (3, None, "'Did Cindy put on any acting today?'"), (4, None, "'These shoes look like I tried too hard when I am going for an easygoing image.'"), (5, None, "'Still, how am I supposed to wear shoes this worn out?'"), (6, None, "'Everyone is waiting, so they sent me to escort you over.'"), (7, None, "'While we are off filming, call a professional company and sanitize my room.'"), (8, None, "'Ugh, what on earth is that smell?'"), (9, None, "'Oh, that smell is not coming from me.'"), (10, None, "'We have fish-sauce props in my backpack right now, and some of it leaked.'"), (11, None, "'Right, I understand.'")]
